function sameFighterProjectiles(target: Readonly<Fighter>, source: Readonly<Fighter>): boolean {
  const targets = target.projectiles;
  const sources = source.projectiles;
  if (targets.length !== sources.length) return false;
  const live = target.projectileSlots > source.projectileSlots ? target.projectileSlots : source.projectileSlots;
  for (let index = 0; index < live; index++) {
    const a = targets[index];
    const b = sources[index];
    if (a === undefined || b === undefined) return false;
    if (a === b) continue;
    if (a.life !== b.life || a.serial !== b.serial || a.kind !== b.kind || a.direction !== b.direction || a.visualFamily !== b.visualFamily || a.newlyReflected !== b.newlyReflected || a.exReach !== b.exReach || a.poolHits !== b.poolHits || a.poolWait !== b.poolWait || a.spec !== b.spec || a.surface !== b.surface) return false;
    if (!sameReal(a.x, b.x) || !sameReal(a.z, b.z) || !sameReal(a.velocityX, b.velocityX) || !sameReal(a.velocityZ, b.velocityZ) || !sameReal(a.damageMultiplier, b.damageMultiplier)) return false;
  }
  return live >= PROJECTILE_CAPACITY || targets[PROJECTILE_CAPACITY - 1]?.visualFamily === sources[PROJECTILE_CAPACITY - 1]?.visualFamily;
}

const sameReal = (a: number, b: number) => a === b && (a !== 0 || 1 / a === 1 / b);

